<script setup lang="ts">
import { computed,ref } from 'vue'
import { onLoad,onUnload,onHide } from '@dcloudio/uni-app'
import FeatureLayout from '../../components/FeatureLayout.vue'
import AppSheet from '../../components/AppSheet.vue'
import { api } from '../../services/api'
import type { Story } from '../../types/domain'
import { errorMessage,requireSession,showMessage } from '../../utils/navigation'
const story=ref<Story|null>(null),index=ref(0),fontSize=ref(18),settings=ref(false),error=ref('')
const chapter=computed(()=>story.value?.chapters?.[index.value])
function save(){if(story.value)uni.setStorageSync('my-legend:reading:'+story.value.id,{chapter:index.value,fontSize:fontSize.value})}
async function load(id:string,requested?:string){if(!requireSession())return;try{story.value=await api.story(id);const saved=uni.getStorageSync('my-legend:reading:'+id);const count=story.value.chapters?.length||0;index.value=Math.max(0,Math.min(count-1,requested!==undefined?Number(requested)||0:saved?.chapter||0));fontSize.value=[16,18,20].includes(saved?.fontSize)?saved.fontSize:18}catch(e){error.value=errorMessage(e)}}
onLoad(q=>{void load(String(q?.id||''),q?.chapter)});onHide(save);onUnload(save)
function next(delta:number){index.value=Math.max(0,Math.min((story.value?.chapters?.length||1)-1,index.value+delta));save();uni.pageScrollTo({scrollTop:0,duration:150})}
function selectChapter(i:number){index.value=i;save();settings.value=false;uni.pageScrollTo({scrollTop:0,duration:150})}
</script>
<template><FeatureLayout :title="story?.title||'阅读故事'" :subtitle="chapter?.title"><view class="reader-body"><view class="row-between"><text class="pill">{{chapter?.source==='demo'?'示例章节':'正文'}}</text><button class="reader-settings" @tap="settings=true">字号与目录</button></view><text v-if="error" class="error-copy">{{error}}</text><template v-else-if="chapter"><text class="reader-title serif">{{chapter.title}}</text><view class="reading-copy" :style="{fontSize:fontSize+'px',lineHeight:1.95}"><text v-for="(paragraph,i) in chapter.paragraphs" :key="i" class="paragraph">{{paragraph}}</text></view><text class="small-note reader-end">这一章读完了，继续下一段旅程。</text></template><text v-else class="copy">正在打开正文，或本作品尚未提供章节。</text></view><view class="reader-controls"><button :disabled="index===0" @tap="next(-1)">上一章</button><button class="audio-button" @tap="showMessage('这篇故事还没有伴读音频')">语音伴读</button><button :disabled="index>=(story?.chapters?.length||1)-1" @tap="next(1)">下一章</button></view><AppSheet title="阅读设置" :open="settings" @close="settings=false"><text class="field-label">文字大小</text><view class="chip-list"><button v-for="size in [16,18,20]" :key="size" class="chip" :class="{selected:fontSize===size}" @tap="fontSize=size;save()">{{size===16?'小':size===18?'标准':'大'}}</button></view><text class="field-label">章节目录</text><button v-for="(item,i) in story?.chapters" :key="item.id" class="directory-item" :class="{selected:i===index}" @tap="selectChapter(i)">{{String(i+1).padStart(2,'0')}}　{{item.title}}</button></AppSheet></FeatureLayout></template>
<style scoped>.reader-body{padding:28rpx 42rpx 190rpx;background:#fff9ed;min-height:75vh}.reader-settings{padding:16rpx;color:#997651;font-size:24rpx}.reader-title{display:block;font-size:45rpx;line-height:1.6;margin:50rpx 0 36rpx}.reading-copy{color:#473728}.paragraph{display:block;margin-bottom:1.5em;white-space:pre-wrap}.reader-end{margin:50rpx 0}.reader-controls{position:fixed;left:0;right:0;bottom:0;padding:22rpx 28rpx calc(28rpx + env(safe-area-inset-bottom,0px));display:flex;gap:20rpx;background:#fff9f0f5;border-top:2rpx solid #eadcc9;z-index:25}.reader-controls button{flex:1;min-height:76rpx;padding:20rpx;color:#856143}.reader-controls button[disabled]{opacity:.35}.reader-controls .audio-button{background:#cf502a;border-radius:99rpx;color:#fff}.directory-item{display:block;text-align:left;width:100%;padding:24rpx 0;border-bottom:2rpx solid #eadcc9}.directory-item.selected{color:#cf502a;font-weight:700}@media(min-width:461px){.reader-controls{max-width:393px;left:50%;transform:translateX(-50%)}}</style>
